  MS (mkR (wz SRO_RSRET) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2 (wz E) (wz P) (wz bs) (wz fb) (wz P) (wz E) a4 a5 a6 a7
          (wz fb) (wz bs) (wz (P + 72)) s5x (wz (E + 16)) (wz (Z.shiftr (P + 72) 3 + 2147450880)) (wz 11) (wz 1)
          (wz (Z.shiftr E 3 + 2147450880)) (wz (Z.shiftr (E + 16) 3 + 2147450880)) t3 t4 t5 t6)
     F (Z_to_bv 64 P_A_HTTP_READ_SOME) fc None m (seg_rom bsegs).

