Definition sro_entry_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo P E bs fb : Z) (c : pcore) (pad7 pad2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' (j8 : list byte) (t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 : word),
       ms' = sro_call_ms sp P E bs fb gp tp t0 t1 t2 a4 a5 a6 a7 (wz 0) t3 t4 t5 t6 F fc m'
    /\ munch [(lo, bv_unsigned sp); (E, E + 24)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -128)
    /\ rw_cells bsegs m' (bv_unsigned sp + -128) ([CB 8 j8; C8 (wz 3); C8 (wz 3)] ++ sro_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells bsegs m' E (ErrCodeCells EC_clear)
    /\ ACONST m'.
