  rw_cells bsegs m P (ParserCoreCells c pad7 pad2) -> pc_state c = 0 -> pcore_ok c -> aapp P PARSER_SIZE -> accessible m P PARSER_SIZE -> P mod 8 = 0 ->
  rw_cells bsegs m E [CB 24 ej] -> aapp E 24 -> accessible m E 24 -> shvis m E (E + 24) -> E mod 8 = 0 ->
  (P + PARSER_SIZE <= E \/ E + 24 <= P) ->
  0 <= bs < 2^64 -> 0 <= fb < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 128 + AINTRIN_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (sro_entry_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo P E bs fb c pad7 pad2 m)
